<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeNameVO;

trait ThemeNameAccessor
{
    private ThemeNameVO $_name;
    public function getName(): string
    {
        return $this->_name->value();
    }
    public function name(): ThemeNameVO
    {
        return $this->_name;
    }
    public function isNameChanged(?self $original = null): bool
    {
        return !$this->_name->equals($original?->_name);
    }
    public function withName(ThemeNameVO|string $name): self
    {
        $copy = clone $this;
        $copy->_name = ThemeNameVO::from($name);
        return $copy;
    }
}
